INSERT [dbo].[Events] ([EventId], [ChapterId], [EventName], [StartDate], [EndDate], [RegistrationStartDate], [RegistrationEndDate], [BannerUrl], [EventCategoryId], [MemberCount], [Location], [City], [StateName], [ZipCode], [EventDetails], [ContactEmail], [IsRegistration], [PageTitle], [MetaDescription], [MetaKeywords], [TopLine], [UpdatedBy], [UpdatedTime], [IsCulturalRegistration], [Flyer], [EarlyBirdCutOfDate], [IsEarlyBird], [IsMemberAmount], [IsNonMemberAmount], [IsActive], [IsQRCode]) VALUES (20377, NULL, N'Independence-Day', CAST(N'2025-08-15T00:00:00.000' AS DateTime), CAST(N'2025-08-15T00:00:00.000' AS DateTime), CAST(N'2025-06-13T00:00:00.000' AS DateTime), CAST(N'2025-07-31T00:00:00.000' AS DateTime), N'20377-independenceday.jpeg', 1, NULL, N'123 Main Street', N'Springfield, IL', NULL, N' 62704', N'<p>
	&nbsp;</p>
<p>
	<strong data-end="20" data-start="0">Varalakshmi Puja</strong> (or <strong data-end="48" data-start="25">Varalakshmi Vratham</strong>) is a Hindu festival dedicated to <strong data-end="102" data-start="83">Goddess Lakshmi</strong>, particularly her form as <strong data-end="144" data-start="129">Varalakshmi</strong>, the giver of boons (&quot;Vara&quot; means boon, &quot;Lakshmi&quot; is the goddess of wealth and prosperity).</p>
<p>
	Celebrated on <strong data-end="356" data-start="300">the second Friday or the Friday before the full moon</strong> in the month of <strong data-end="385" data-start="373">Shravana</strong> (July&ndash;August) per the South Indian calendar.</p>
<p>
	To seek the blessings of <strong data-end="498" data-start="481">Ashta Lakshmi</strong> &mdash; the eight forms of Lakshmi representing various types of wealth (material, spiritual, progeny, courage, etc.).</p>
<p>
	Primarily <strong data-end="667" data-start="650">married women</strong> in South India (Tamil Nadu, Karnataka, Andhra Pradesh, Telangana), though anyone can observe it with devotion.</p>
', N'wwtewreroyetuit@gmail.com', 1, N'No', NULL, NULL, N'SpecialOffer', N'EST', CAST(N'2025-07-26T21:55:38.223' AS DateTime), 1, N'20377-independenceday.png', CAST(N'2025-06-30T00:00:00.000' AS DateTime), 1, NULL, NULL, 1, N'Multiple')
GO
