INSERT [dbo].[PageDetails] ([PageDetailId], [Heading], [Description], [PageUrl], [DocumentUrl], [Target], [PageTitle], [MetaDescription], [MetaKeywords], [TopLine], [IsActive], [UpdatedBy], [UpdatedDate], [InsertedBy], [InsertedDate], [OtherUrl], [AddPage]) VALUES (10463, N'President’s Message', N'<div class="text-start">
	<div style="float: right; padding-left: 15px; padding-bottom: 15px; display: flex; flex-direction: column; align-items: center; justify-content: center;">
		<a href="content/User/images/data-president.jpg"><img alt="" src="content/User/images/data-president.jpg" style="overflow: hidden;border: 1px solid #ff3f3e;padding: 4px;border-radius: 90px;width: 170px !important;height: 170px !important;object-fit: cover;float: none !important;box-shadow: rgba(0, 0, 0, 0.45) 0px 25px 20px -20px;margin-bottom: 10px;" /></a>
		<h4>
			Hari Dornala</h4>
		<h5 style="color: #ff3f3e;">
			President, Association Name</h5>
	</div>
	<div class="pt-3">
		<p>
			<b>Namaskaram!</b></p>
		<p>
			It is with great pride and enthusiasm that I welcome you to Telugu Association Tool , an innovative platform designed to bring together and empower the Telugu community across the globe. As the President of this esteemed association, I believe in the strength of our collective heritage, culture, and values. This platform is a reflection of our commitment to preserving and promoting Telugu traditions while embracing the advancements of modern technology.</p>
		<p>
			Telugu Association Tool&nbsp; is built to serve as a digital bridge that connects us, no matter where we are. Whether you&rsquo;re organizing a cultural event, managing memberships, or simply looking to connect with fellow Telugu-speaking individuals, this platform provides everything you need at your fingertips. Our goal is to make it easier for you to stay connected, celebrate our vibrant culture, and contribute to the growth of our community.</p>
		<p>
			As we continue to grow, I am confident that this tool will be instrumental in strengthening our bonds and expanding our reach. I encourage every member of our association to take full advantage of its features, and together, let us build a more connected and empowered Telugu community.</p>
		<p>
			Thank you for being a part of this journey. I look forward to the continued success of our association and the positive impact we can achieve together.</p>
	</div>
	<div class="d-flex flex-column align-items-end fnt-ram">
		<div class="text-start me-4">
			<h4 class="presid-name mt-2 pb-2 border-bottom " style="color: #fe6600;font-family: Poppins-Regular;font-weight: 400;font-style: normal;margin-bottom: 10px;margin-top: 10px;    text-align: center;
    font-size: 20px;">
				&nbsp; Warm regards,</h4>
			<h4 class="presid-name mt-2" style="
        text-align:center; font-size: 18px;
    ">
				President,</h4>
			<h4 class="presid-name mb-2 fnt-ram pb-2" style="font-size: 18px; text-align:center;">
				&nbsp; &nbsp;&nbsp; Telugu Association.</h4>
		</div>
	</div>
</div>
', N'president’s-message', N'', N'', N'President’s Message | Telugu Association – A Vision for Growth & Unity', N'Read the President’s message of our Telugu Association. Learn about our vision, mission, and dedication to preserving Telugu culture, language, and community values.', N'President’s message Telugu association, leadership message Telugu, Telugu association vision, Telugu community leadership, about Telugu association, Telugu culture, Telugu nonprofit, Telugu heritage, Telugu unity', N'', 1, N'support@arjunweb.in', CAST(N'2025-05-30T12:05:15.223' AS DateTime), N'techsupport@arjunweb.in', CAST(N'2023-07-15T07:08:15.213' AS DateTime), N'', N'Only Page')
